			/*
			 * 위험요인 계산-young 같이 사용 
			*/

			function riskFctrYoungResult() {
			    var dmList = app.lookup("dmList");
			    var dmList2 = app.lookup("dmList2");
			    var dsList = app.lookup("dsList");
			    
			    var indvResult = ValueUtil.fixNumber(0);    //개인영역
			    var houseResult = ValueUtil.fixNumber(0);   //가정영역
			    var fridaResult = ValueUtil.fixNumber(0);   //또래 학교
			    var riskSumResult = ValueUtil.fixNumber(0); //합계
			    
			    for (var i = 0; i < dsList.getRowCount(); i++) {
			        var rspnsValue = dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE");
			        
			        if (rspnsValue != "1") {
			            rspnsValue = "0";
			        }
			        
			        if (i >= 0 && i < 7) {
			            indvResult += ValueUtil.fixNumber(rspnsValue); //개인영역
			        }
			        
			        if (i >= 7 && i < 13) {
			            houseResult += ValueUtil.fixNumber(rspnsValue); //가정영역
			        }
			        
			        if (i >= 13 && i < 19) {
			            if (i == 18) console.log(rspnsValue);
			            fridaResult += ValueUtil.fixNumber(rspnsValue);  //또래 학교
			        }
			        
			        riskSumResult += ValueUtil.fixNumber(rspnsValue);  //합계       
			    }
			    
			    var riskDgreeResult = "";
			    
			    if (riskSumResult < 5) {
			        riskDgreeResult = "1";
			    }

			    if (riskSumResult >= 5 && riskSumResult <= 9) {
			        riskDgreeResult = "2";
			    }

			    if (riskSumResult >= 10) {
			        riskDgreeResult = "3";
			    }
			    
			    dmList.setValue("01", indvResult); //개인영역
			    dmList.setValue("02", houseResult); //가정영역
			    dmList.setValue("03", fridaResult); //또래 학교
			    dmList2.setValue("RISK_FCTR_SUM_SCORE", riskSumResult);        //위험요인합계점수
			    dmList2.setValue("RISK_FCTR_DGREE_SE_CD", riskDgreeResult); //위험요인정도구분코드

			    util.Control.redraw(app, "grpCont2");

			}

