			/*
			 * 위기문제행동 계산 - young
			*/

			function crisisFctrYoungResult() {
			    var dmList = app.lookup("dmList");
			    var dmList2 = app.lookup("dmList2");
			    var dsList = app.lookup("dsList2");
			    
			    var intnetResult = ValueUtil.fixNumber(0);       //인터넷중독
			    var schlViolncResult = ValueUtil.fixNumber(0);   //학교폭력
			    var housekViolncResult = ValueUtil.fixNumber(0); //가정폭력
			    var chilIltrtResult = ValueUtil.fixNumber(0);    //아동학대
			    var lvmResult = ValueUtil.fixNumber(0);          //가출
			    var sucdeResult = ValueUtil.fixNumber(0);        //자살
			    var crisisSumResult = ValueUtil.fixNumber(0);    //합계

			    for (var i = 0; i < dsList.getRowCount(); i++) {
			        
			        var rspnsValue = dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE");
			        
			        if (rspnsValue != "1") {
			            rspnsValue = "0";
			        }
			        
			        if (i == 0 ) {
			            intnetResult += ValueUtil.fixNumber(rspnsValue); //인터넷중독
			        }
			        
			        if (i >= 1 && i < 5) {
			            schlViolncResult += ValueUtil.fixNumber(rspnsValue); //학교폭력
			        }
			        
			        if (i >= 5 && i < 7) {
			            housekViolncResult += ValueUtil.fixNumber(rspnsValue); //가정폭력
			        }

			        if (i >= 7 && i < 11) {
			            chilIltrtResult += ValueUtil.fixNumber(rspnsValue); //아동학대
			        }
			        
			        if (i == 11) {
			            lvmResult += ValueUtil.fixNumber(rspnsValue); //가출
			        }

			        if (i == 12) {
			            sucdeResult += ValueUtil.fixNumber(rspnsValue); //자살
			        }

			        crisisSumResult += ValueUtil.fixNumber(rspnsValue); //합계       
			    }
			    
			    var crisisDgreeResult = "";

			    if (crisisSumResult > 0) {
			       crisisDgreeResult = "3";  //고위험군         
			    } else {
			       crisisDgreeResult = "1";  //해당업음 
			    }

			    dmList.setValue("05", intnetResult); //인터넷
			    dmList.setValue("07", schlViolncResult); //학교폭력
			    dmList.setValue("08", housekViolncResult); //가정폭력
			    dmList.setValue("09", chilIltrtResult);   //아동학대
			    dmList.setValue("11", lvmResult);   ////가출
			    dmList.setValue("13", sucdeResult);   //자살
			    dmList2.setValue("CRISIS_PROBM_SUM_SCORE", crisisSumResult);        //위기요인합계점수
			    dmList2.setValue("CRISIS_PROBM_DGREE_SE_CD", crisisDgreeResult); //위기요인정도구분코드

			    util.Control.redraw(app, "grpCont4");
			    
			}

